import glob, re

pattern = re.compile(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} \[([A-Z]+)\] ')

non_matching_lines = []
for filepath in glob.glob('/app/logs/*.log'):
