import glob, os, datetime, re
from collections import Counter, defaultdict

REF_DATE = datetime.date(2025, 8, 12)

# Define date ranges
# today: 2025-08-12
# last_7_days: 2025-08-06 to 2025-08-12 (7 days inclusive)
# last_30_days: 2025-07-14 to 2025-08-12 (30 days inclusive)
# month_to_date: 2025-08-01 to 2025-08-12 (Aug 1 to Aug 12 inclusive)
# total: all

ranges = {
    'today': lambda d: d == REF_DATE,
    'last_7_days': lambda d: (REF_DATE - datetime.timedelta(days=6)) <= d <= REF_DATE,
    'last_30_days': lambda d: (REF_DATE - datetime.timedelta(days=29)) <= d <= REF_DATE,
    'month_to_date': lambda d: datetime.date(REF_DATE.year, REF_DATE.month, 1) <= d <= REF_DATE,
    'total': lambda d: True
}

counts = {period: Counter() for period in ranges}

pattern = re.compile(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[([A-Z]+)\]')

for filepath in glob.glob('/app/logs/*.log'):
    with open(filepath, 'r') as f:
        for line in f:
            m = pattern.match(line)
            if m:
                d_str, sev = m.group(1), m.group(2)
                if sev in ('ERROR', 'WARNING', 'INFO'):
                    d = datetime.date.fromisoformat(d_str)
                    for period, fn in ranges.items():
                        if fn(d):
                            counts[period][sev] += 1

print('period,severity,count')
for period in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    for sev in ['ERROR', 'WARNING', 'INFO']:
        print(f'{period},{sev},{counts[period][sev]}')
