import glob, os, datetime, re
from collections import Counter

daily_counts = {}

pattern = re.compile(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[([A-Z]+)\]')

for filepath in sorted(glob.glob('/app/logs/*.log')):
    with open(filepath, 'r') as f:
        for line in f:
            m = pattern.match(line)
            if m:
                d_str, sev = m.group(1), m.group(2)
                if sev in ('ERROR', 'WARNING', 'INFO'):
                    d = datetime.date.fromisoformat(d_str)
                    if d not in daily_counts:
                        daily_counts[d] = Counter()
                    daily_counts[d][sev] += 1

sorted_dates = sorted(daily_counts.keys())
print(f'Total dates recorded: {len(sorted_dates)}')
for d in sorted_dates[-15:]:
    print(d, dict(daily_counts[d]))
